(globalThis.CATALOGUE_RECORD_CHUNKS??=Object.create(null))[234]={"source_order":234,"notes":["The superscript after '117' is read as 'b'. The letterform could alternatively be read as '6'. 'b' is consistent with the folio label.","The grey streak at about x=1800, y=3200 might be a very faint pencil stroke. No letters are discernible in it.","The page has printed ruling with no catalogue entries on any ruled line.","Faint ghosted letterforms are visible across the page. They appear to be show-through or offset from the writing on the reverse side or the facing folio (compare fol. 117 and fol. 118). They are not target-page text and are not transcribed.","The right edge is the gutter and sewing side. The left edge shows the stacked edges of the leaves.","I reviewed the overview and all six native tiles. The ruled lines carry no catalogue entries, headings, cross-references or marginal notes at the top, middle, bottom, outer edge or gutter.","Faint ghosted letterforms appear across the ruled area. They are show-through or offset from writing on adjacent leaves (compare fol. 117 and fol. 118) and are not transcribed as target text.","There is a small dark smudge or blot at about x=590–660, y=2415–2530. It is not legible as text.","There is a faint short grey vertical streak at about x=1790–1820, y=3165–3260. It may be a pencil trace or abrasion, and no letters can be made out.","There are tiny ink specks at about x=1185–1265, y=1315–1360. They are not text.","The right (gutter) edge shows sewing thread at about y=3620–4380, plus a small torn paper or tissue fragment at about y=2590–2700. These are physical features, not writing.","The raised character after '117' is graphically ambiguous between 'b' and '6'. The reading 'b' is supported mainly by the supplied folio label, not independently by the letterform."],"records":[{"id":"css-prod-0234-r001","local_id":"r001","source_order":234,"folio":"117b","folio_label":"fol. 117b","sequence":1,"page_id":"757f732e-8fdf-4db6-8e8a-e23d04b77f30","kind":"other","record_type":"non_catalogue_text","source_model_record_type":"non_catalogue_text","subtype":"folio_number","shelfmark":"","titleLiteral":"","titleNormalized":"","displayTitle":"Catalogue text","authorOrSource":"","source":"","subject":"","subjectGroup":"","date":"","extent":"","lines":"","script":"","incipit":"","transcription":"117ᵇ","annotations":["Ink folio number in the top-left corner of the page, at about x=405–525, y=330–430 in native coordinates.","The final character is written raised, as a superscript after '117'."],"uncertainties":["The superscript letterform could be read as 'b' or as '6'. It is read as 'b' because that agrees with the supplied folio label 'fol. 117b'.","The raised character after '117' is graphically ambiguous between 'b' and '6'. The reading 'b' is supported mainly by the supplied folio label, not independently by the letterform."],"focused_readings":[],"reviewNotes":[],"editorialNotes":[],"relationships":[],"editorial_context":[],"block_ids":["b001"],"locations":[{"block_id":"b001","bbox":[405,330,120,100]}],"isCancelled":false,"needsReview":true,"human_verified":false,"verification_status":"machine_reviewed","change_audit":[],"sourceCitationURL":"https://iiif.bodleian.ox.ac.uk/iiif/canvas/757f732e-8fdf-4db6-8e8a-e23d04b77f30.json","auditPath":"audit/pages/0234.json","attachedNotes":[],"resolvedRelationships":[],"attachedRecords":[]}]};
